def pre(xs):
    if len(xs) > 5:
        return False
    for x in xs:
        if x < 0 or x > 6:
            return False
    return True

def _expected_split(xs):
    total = sum(xs)
    if total % 2 == 1:
        return False
    target = total // 2
    if target < 0:
        return False

    reachable = [True]
    for i in range(target):
        reachable.append(False)

    for x in xs:
        if x < 0:
            continue
        s = target
        while s >= x:
            if reachable[s - x]:
                reachable[s] = True
            s = s - 1

    return reachable[target]

def post(xs, result):
    return result == _expected_split(xs)
